    // Class to represent Huffman tree node
class Node {
    constructor(d, i, left = null, right = null) {
        // frequency
        this.data = d;

        // smallest original index in subtree
        this.index = i;

        this.left = left;
        this.right = right;
    }
}

// Function to traverse tree in preorder
// manner and push the Huffman representation
// of each character.
function preOrder(root, ans, curr) {
    if (root === null) return;

    // Leaf node represents a character.
    if (root.left === null && root.right === null) {
        // single character case
        if (curr === "") curr = "0";
        ans.push(curr);
        return;
    }

    preOrder(root.left, ans, curr + '0');
    preOrder(root.right, ans, curr + '1');
}

// Huffman Codes function
function huffmanCodes(s, freq) {

    let n = s.length;

    // Min heap simulation
    let pq = [];

    for (let i = 0; i < n; i++) {
        pq.push([freq[i], i, new Node(freq[i], i)]);
    }

    // single character case
    if (n === 1) return ["0"];

    // Construct Huffman tree
    while (pq.length > 1) {

        pq.sort((a, b) => {
            // smaller freq first
            if (a[0] !== b[0]) return a[0] - b[0];
            // when freq are equal
            return a[1] - b[1];
        });

        // Left node
        let l = pq.shift();

        // Right node
        let r = pq.shift();

        // internal node (same as C++)
        let newNode = new Node(
            l[0] + r[0],
            Math.min(l[1], r[1]),
            l[2],
            r[2]
        );

        pq.push([newNode.data, newNode.index, newNode]);
    }

    let root = pq[0][2];

    let ans = [];
    preOrder(root, ans, "");

    return ans;
}


